const updateOrchestratorReplacement = `-- name: UpdateOrchestratorReplacement :execrows
UPDATE orchestrator_replacements
SET phase = ?, is_active = ?, revision = revision + 1, state_json = ?, updated_at = ?
WHERE id = ? AND revision = ?
`

type UpdateOrchestratorReplacementParams struct {
	Phase     string
	IsActive  bool
	StateJson string
	UpdatedAt string
	ID        string
	Revision  int64
}

func (q *Queries) UpdateOrchestratorReplacement(ctx context.Context, arg UpdateOrchestratorReplacementParams) (int64, error) {
	result, err := q.db.ExecContext(ctx, updateOrchestratorReplacement,
		arg.Phase,
		arg.IsActive,
		arg.StateJson,
		arg.UpdatedAt,
		arg.ID,
		arg.Revision,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected()
}
